True from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    shapes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if len(cells) >= 2:
                r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
                c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
                area = (r1-r0+1)*(c1-c0+1)
                if len(cells) / area >= 0.75:
                    shapes.append((color, r0, r1, c0, c1))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for color, r0, r1, c0, c1 in shapes:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out
